    "year": 1988,
    "author": "天命人 @齐天",
    "avatar": "📱",
    "timestamp": "放学路上",
    "content": "1988年那一幕真让人难忘：那年第一次跟着老爹去茶馆听书，台上说书人醒木一拍啪嗒作响，满堂茶客屏息凝神，那一刻我真正体会到了华夏故事的魅力。",
    "reply": "醒木一声惊天地，方寸书台纳乾坤。华夏文脉的生生不息，就藏在这一声声评书里。",
