    "author": "@弄堂阿飞",
    "avatar": "🎮",
    "timestamp": "除夕夜",
    "content": "1988年那一幕真让人难忘：那年骑单车穿过刚刚通车的大桥，江风猎猎吹起衣角，看着脚下奔腾东流的江水，心里满是对明天最纯净的向往。",
    "reply": "江水奔流不息，岁月呼啸向前。当年在桥头迎风而立的少年，始终不曾停下追光的脚步。",
