    "content": "1998年独家记忆（#1）：1998年那一幕真让人难忘：那年第一次跟着老爹去茶馆听书，台上说书人醒木一拍啪嗒作响，满堂茶客屏息凝神，那一刻我真正体会到了华夏故事的魅力。",
    "reply": "醒木一声惊天地，方寸书台纳乾坤。华夏文脉的生生不息，就藏在这一声声评书里。",
    "likes": 180,
    "pinType": "clip",
    "tilt": 0.5,
