    "id": "seed-1999-01",
    "year": 1999,
    "author": "@单车后座的夏天",
    "avatar": "🕹️",
    "timestamp": "除夕夜",
    "content": "1999年那会儿，全家人最关心的莫过于《澳门回归《七子之歌》与世纪末预言》，老爸特意买了两份当天的晚报剪贴在硬皮笔记本里，边剪边感叹历史走得真快。",
    "reply": "剪报本上的浆糊干了，但那一页发黄的文字，记录了普通人家与大时代同频共振的心跳。",
    "likes": 253,
    "pinType": "pin",
    "tilt": -0.8,
