    "author": "@老弄堂修理工",
    "avatar": "🚲",
    "timestamp": "刚刚",
    "content": "那年放暑假，我和发小在树荫下喝着冰镇汽水，收音机里正热播关于澳门回归的新闻，蝉鸣声震耳欲聋，那是我们最无忧无虑的一个夏天。",
    "reply": "汽水喝完了，蝉声也停了，但那个午后透过树叶洒下来的阳光，永远留在了记忆深处。",
