    "year": 2002,
    "author": "红土旅人 @阿峰",
    "avatar": "🛹",
    "timestamp": "1小时前",
    "content": "那年放暑假，我和发小在树荫下喝着冰镇汽水，收音机里正热播关于大片时代的新闻，蝉鸣声震耳欲聋，那是我们最无忧无虑的一个夏天。",
    "reply": "汽水喝完了，蝉声也停了，但那个午后透过树叶洒下来的阳光，永远留在了记忆深处。",
    "likes": 63,
