    "id": "seed-2002-04",
    "year": 2002,
    "author": "@弄堂阿飞",
    "avatar": "🎆",
    "timestamp": "昨天",
    "content": "大年初一全家吃完团圆饭，围坐在一起聊起2002年的点点滴滴，奶奶拿出珍藏的老相册，指着黑白合影给我们讲她当年的青春往事。",
    "reply": "相册翻动的沙沙声，是几代人血脉温情最深沉的对话，时间带不走爱的印记。",
