    "content": "那年刚到省城打拼，兜里揣着刚发的一百块工资，路过商场大屏幕看到《《那些年我们一起追的女孩》与微信上线》的画面，暗下决心一定要在这个城市扎下根来。",
    "reply": "当年站在大屏幕前仰望的年轻行者，如今早已在时光的淬炼中长成了参天大树。",
