    "timestamp": "放学路上",
    "content": "在旧书市淘到了一本2013年的《大众电影》画报，封面正是当年的时代偶像，扉页上还留着上一位主人用蓝色圆珠笔写的随笔。",
    "reply": "旧画报就像一扇时光窄门，轻轻一推，当年的风华绝代与人间喧嚣便扑面而来。",
