    "content": "那年学校组织元旦文艺汇演，全班排练了关于大黄鸭的情景剧，我们在黑板上画满了彩球和气球，演出结束时全场掌声雷动。",
    "reply": "黑板上的彩色粉笔字早已擦去，但那阵青春热烈的掌声，在心里回荡了一辈子。",
