    "content": "那年收到大学录取通知书那天，正好赶上《巨型大黄鸭游进维港与致青春热映》的全国转播，老妈一边做红烧肉一边偷偷抹眼泪。",
    "reply": "母亲的眼泪是欣慰也是不舍，那一碗红烧肉的滋味，胜过人间所有盛宴。",
