    "id": "seed-2017-12",
    "year": 2017,
    "author": "拾得先锋 @林夕海",
    "avatar": "🎧",
    "timestamp": "放学路上",
    "content": "2017年那一幕真让人难忘：那年骑单车穿过刚刚通车的大桥，江风猎猎吹起衣角，看着脚下奔腾东流的江水，心里满是对明天最纯净的向往。",
    "reply": "江水奔流不息，岁月呼啸向前。当年在桥头迎风而立的少年，始终不曾停下追光的脚步。",
    "likes": 68,
    "pinType": "tape",
    "tilt": -1.2,
